impl<S, B> Service<Request<B>> for Timing<S> where S: Service<Request<B>> {
    type Response = S::Response;
    type Error = S::Error;
    type Future = S::Future;
    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)                   // forward readiness
    }
    fn call(&mut self, req: Request<B>) -> Self::Future {
        metrics::record_start(Instant::now());
        self.inner.call(req)                        // continue the chain
    }
}

